/* ============================================
   POSITIONING HELPERS
   ============================================ */
.gear-tab,
.combat-tab {
  position: relative !important;
  display: block !important;
  height: auto !important;
  overflow: visible !important;
  margin-left: 51px; /* (800px tab - $content-width) / 2 = 51px to center */
  margin-right: 51px; /* mirror left margin so right border art is not covered */
  /* Match scrollbar styling from gear tab */
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 0, 0, 0.4) transparent;
}
.gear-tab::-webkit-scrollbar,
.combat-tab::-webkit-scrollbar {
  width: 3px;
}
.gear-tab::-webkit-scrollbar-track,
.combat-tab::-webkit-scrollbar-track {
  background: transparent;
}
.gear-tab::-webkit-scrollbar-thumb,
.combat-tab::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.4);
  border-radius: 2px;
}
.gear-tab::-webkit-scrollbar-thumb:hover,
.combat-tab::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.6);
}

.gear-tab {
  margin-top: 0px;
}

.combat-tab {
  margin-top: 15px;
}

.combat-tab {
  /* Push weapons section down below the encumbrance bar */
  /* Armor section sits below weapons section */
}
.combat-tab .item-category:first-of-type {
  margin-top: 20px;
}
.combat-tab .item-category:nth-of-type(2) {
  margin-top: 130px;
}

.item-category {
  border-left: none;
  border-right: none;
  border-radius: 0 0 5px 5px; /* Only round bottom corners since title is separate */
  border-top: none; /* No top border - title provides visual separation */
  margin-top: 10px; /* Remove negative margin */
  margin-bottom: 25px;
  position: relative;
  z-index: 5; /* Above combat stats (z-index: 1) to obscure them when scrolling */
  background-color: #b5ddb4; /* Solid background to obscure content underneath */
}
.item-category::before {
  content: "";
  position: absolute;
  left: 0px;
  right: 0px;
  top: 0;
  bottom: 0;
  pointer-events: none;
}

.osp.sheet.actor .item-category-title {
  background: #000;
  border-bottom: none;
  padding: 2px 0px 0 0px;
  margin-top: 0px;
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif !important;
  font-size: 14px !important;
  color: #fff;
  font-weight: bold !important;
  cursor: pointer;
  display: grid !important;
  grid-auto-flow: dense;
  grid-template-columns: 18px 485px 55px 55px 103px;
  align-items: center;
  text-align: center;
  gap: 0px;
  height: 28.5px;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 5px 5px 0 0;
  position: relative;
  z-index: 11; /* Above encumbrance bar (z-index: 10) and item-category body */
}
.osp.sheet.actor .item-category-title > * {
  grid-row: 1 !important;
  position: absolute !important;
  top: 0;
  height: 28.5px;
  display: flex !important;
  align-items: center;
  padding: 0 !important;
  width: auto !important;
  white-space: nowrap;
  transform: translateX(-50%);
}
.osp.sheet.actor .item-category-title > :nth-child(1) {
  left: 9px;
}
.osp.sheet.actor .item-category-title > :nth-child(2) {
  left: 38px;
  transform: none;
}
.osp.sheet.actor .item-category-title > :nth-child(3) {
  left: 492px;
}
.osp.sheet.actor .item-category-title > :nth-child(4) {
  left: 547px;
}
.osp.sheet.actor .item-category-title .item-roll-icon {
  height: auto;
}

.combat-tab .item-roll-icon {
  justify-self: center;
}

.combat-tab .item-entry.item[draggable=true] {
  cursor: grab;
}

.combat-tab .item-entry.item.dragging {
  opacity: 0.4;
}

.combat-tab .item-entry.item.drag-over {
  background-color: rgba(180, 0, 0, 0.25);
}

.gear-tab .item-entry {
  position: relative;
}

.item-sort-controls {
  position: absolute;
  left: -20px;
  top: calc(60px / 2 - 11px);
  width: 16px;
  height: 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 12;
  pointer-events: auto;
}

.gear-tab .item-entry:hover > .item-sort-controls,
.item-sort-controls:hover {
  opacity: 0.6;
}

.item-sort-up,
.item-sort-down {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 10px;
  cursor: pointer;
  color: #333;
  font-size: 11px;
  line-height: 1;
}
.item-sort-up:hover,
.item-sort-down:hover {
  color: #000;
  opacity: 1 !important;
}

