.ability:has(.attr-str) {
  --field-left: 47px;
}

.ability:has(.attr-int) {
  --field-left: 168px;
}

.ability:has(.attr-wis) {
  --field-left: 288px;
}

.ability:has(.attr-dex) {
  --field-left: 408px;
}

.ability:has(.attr-con) {
  --field-left: 528px;
}

.ability:has(.attr-cha) {
  --field-left: 648px;
}

