  margin: 6px 0 0;
  padding: 7px 12px;
  color: #f7e8c5;
  background: linear-gradient(145deg, #65492c, #3b291b);
  border: 1px solid #745333;
  border-radius: 5px;
  text-align: center;
}

.spell-formula-header {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif !important;
  font-size: 10px;
  color: #dfc792;
  margin-bottom: 2px;
}

.spell-formula-slots {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif !important;
  font-size: 10px;
  color: #f4e5c1;
}
.spell-formula-slots b {
  color: #f6cf72;
}

.spell-no-slots {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 22px;
  color: #888;
  text-align: center;
  padding: 10px;
}

/* Sub-tab container */
.spell-subtabs {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Sub-tab nav bar */
.spell-subtab-nav {
  flex-shrink: 0;
  display: flex;
  gap: 5px;
  margin: 4px 30px 8px;
  padding: 5px;
  border: 1px solid rgba(69, 47, 27, 0.35);
  border-radius: 6px;
  background: rgba(255, 246, 215, 0.28);
}

.spell-subtab-btn {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif !important;
  flex: 1 1 0;
  font-size: 14px;
  font-weight: bold;
  color: #5f4b35;
  padding: 7px 12px;
  text-align: center;
  cursor: pointer;
  border: 1px solid rgba(69, 47, 27, 0.24);
  border-radius: 4px;
  background: rgba(255, 248, 220, 0.42);
  user-select: none;
  transition: color 0.1s, background 0.1s, border-color 0.1s;
}
.spell-subtab-btn:hover {
  color: #2c1810;
  border-color: rgba(69, 47, 27, 0.45);
  background: rgba(255, 248, 220, 0.7);
}
.spell-subtab-btn.active {
  color: #fff0c6;
  border-color: #4a321e;
  background: linear-gradient(#72502c, #3d2b1a);
}

/* Sub-tab panels — hidden by default, shown when .active */
.spell-subtab-panel {
  display: none;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 8px 30px 20px;
  scrollbar-width: none;
}
.spell-subtab-panel::-webkit-scrollbar {
  display: none;
}
.spell-subtab-panel.active {
  display: block;
}

.spell-level-group {
  margin-bottom: 10px;
}

.spell-level-heading {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 26px;
  font-weight: bold;
  color: #2c1810;
  border-bottom: 1px solid rgba(44, 24, 16, 0.3);
  padding: 3px 4px 4px;
  margin-bottom: 4px;
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.spell-level-heading:hover {
  background: rgba(44, 24, 16, 0.04);
  border-radius: 3px;
}
.spell-level-heading .spell-level-slots {
  font-weight: normal;
  font-size: 22px;
  color: #666;
}

.spell-level-caret {
  font-size: 14px;
  color: #704214;
  flex-shrink: 0;
  line-height: 1;
}

/* Collapse spell entries when group is collapsed */
.spell-level-group.collapsed .spell-entry {
  display: none;
}

.spell-entry {
  border-radius: 3px;
  margin-bottom: 2px;
  width: 100%;
  box-sizing: border-box;
}
.spell-entry:hover > .spell-entry-header {
  background: rgba(112, 66, 20, 0.07);
}

.spell-entry-header {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 8px;
  padding: 4px 6px;
  cursor: pointer;
  border-radius: 3px;
  user-select: none;
  width: 100% !important;
  box-sizing: border-box;
}

.spell-entry-chevron {
  font-size: 14px;
  color: #704214 !important;
  flex: 0 0 auto !important;
  line-height: 1;
}

.spell-entry-name {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 24px;
  font-weight: bold;
  color: #1a1a1a !important;
  flex: 1 1 auto !important;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.spell-reversible-tag {
  font-size: 18px;
  font-weight: bold;
  color: #704214 !important;
  background: rgba(112, 66, 20, 0.12);
  border-radius: 2px;
  padding: 0 4px;
  vertical-align: middle;
}

.spell-entry-meta {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 20px;
  color: #666 !important;
  white-space: nowrap;
  flex: 0 0 auto !important;
}

/* Spell action icons (span, not button, to avoid Foundry button CSS) */
.spell-known-btn,
.spell-learn-btn,
.spell-cast-btn,
.spell-pray-btn {
  display: inline-block !important;
  flex: 0 0 auto !important;
  padding: 0 2px;
  line-height: 0;
  cursor: pointer;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  background: none !important;
}
.spell-known-btn img,
.spell-learn-btn img,
.spell-cast-btn img,
.spell-pray-btn img {
  display: block;
  width: 24px;
  height: 24px;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}
.spell-known-btn:hover img,
.spell-learn-btn:hover img,
.spell-cast-btn:hover img,
.spell-pray-btn:hover img {
  opacity: 0.75;
}

.spell-entry-body {
  display: none;
  padding: 4px 14px 8px 32px;
}

.spell-entry.open > .spell-entry-body {
  display: block;
}

.spell-description {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 22px;
  color: #333 !important;
  margin: 0 0 4px;
  line-height: 1;
}

.spell-reversed-block {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid rgba(112, 66, 20, 0.25);
}

.spell-reversed-name {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 22px;
  font-weight: bold;
  color: #704214 !important;
  margin-bottom: 2px;
}

.spell-no-spells {
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
  font-size: 22px;
  color: #888 !important;
  text-align: center;
  padding: 20px;
}

