/* OSP Bio language disclosure */
/* Languages stay on one readable line; long lists expand into an anchored parchment popover. */
.languages-row.open-language-dialog {
  width: var(--languages-row-width, 272px);
  height: 33px;
  min-height: 30px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  z-index: var(--z-lang-row, 101);
}

.cs-languages-field {
  position: relative;
  overflow: visible;
}

.languages-tags {
  display: block;
  width: 100%;
  margin-right: 0;
  line-height: 1;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis;
  font-size: var(--languages-font-size, 22px) !important;
  padding: 0 4px;
  text-align: center;
  word-wrap: normal;
}

.cs-languages-field.has-language-overflow .languages-tags {
  width: calc(100% - 24px);
  margin-right: 24px;
}

.cs-languages-toggle {
  position: absolute;
  right: 2px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  padding: 0;
  border: 1px solid rgba(120, 105, 77, 0.65);
  border-radius: 50%;
  background: #f4e7c3;
  color: #78694D;
  cursor: pointer;
  z-index: 3;
}

.cs-languages-toggle[hidden] {
  display: none;
}

.cs-languages-expanded {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  min-height: 25px;
  padding: 8px 10px;
  background: #f4e7c3;
  border: 1px solid #78694D;
  color: #2b2116;
  line-height: 1.2;
  white-space: normal;
  overflow-wrap: anywhere;
  text-align: left;
  font-size: 22px;
  z-index: 200;
  box-shadow: 0 3px 8px rgba(43, 33, 22, 0.25);
}

.cs-languages-expanded[hidden] {
  display: none !important;
}

/* Keep the disclosure above the fixed Bio header rows and reserve caret space
   against the Explorer's Journal skin's existing language-column overrides. */
.osp #languages-container#languages-container#languages-container:has(.cs-languages-expanded:not([hidden])) {
  z-index: 200 !important;
}
.osp #languages-container#languages-container#languages-container .cs-languages-toggle {
  width: 22px !important;
  height: 22px !important;
  min-height: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
  font-size: 11px !important;
  color: #78694D !important;
  background: #f4e7c3 !important;
}
.osp #languages-container#languages-container#languages-container .cs-languages-toggle[hidden] {
  display: none !important;
}
.osp #languages-container#languages-container#languages-container .cs-languages-expanded {
  font-size: 22px !important;
  line-height: 1.2 !important;
  background: #f4e7c3 !important;
  white-space: normal !important;
  overflow: visible !important;
}

.osp form.ej-sheet #languages-container#languages-container#languages-container .cs-languages-field .languages-tags {
  display: block !important;
  height: auto !important;
  align-self: center !important;
  line-height: 1 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  text-overflow: ellipsis !important;
}

.osp form.ej-sheet #languages-container#languages-container#languages-container .cs-languages-field.has-language-overflow .languages-tags {
  width: calc(75% - 24px) !important;
  margin-right: 24px !important;
}

