/* Spell cast chat card */
.osp-spell-cast-card {
  border: 1px solid #704214;
  border-radius: 4px;
  background: #fdf8f0;
  padding: 6px 8px;
  font-family: "Cooper Std", "Cooper Standard", Georgia, serif;
}
.osp-spell-cast-card .spell-card-header {
  border-bottom: 1px solid #c9a87c;
  padding-bottom: 4px;
  margin-bottom: 5px;
}
.osp-spell-cast-card .spell-card-name {
  font-size: 15px;
  font-weight: bold;
  color: #1a1a1a;
  margin: 0 0 2px;
}
.osp-spell-cast-card .spell-card-type {
