/* Foundry core's FilePicker "Favorites" quick-access buttons (e.g. Images/fonts) render with
   near-identical text and background colors in this environment, making them hard to read.
   This is core UI, not part of our sheet, so it's patched globally rather than under .osp. */
.filepicker .favorites .path {
  background: rgba(0, 0, 0, 0.45);
}
.filepicker .favorites .path a.link {
  color: #f0e6d2;
}
.filepicker .favorites .path a.remove {
  color: #f0e6d2;
  opacity: 0.85;
}
.filepicker .favorites .path a.remove:hover {
  opacity: 1;
}

/* Grid overlay animation */
.grid-overlay {
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.osp select {
  color-scheme: light;
  color: #34271b;
  accent-color: #34432c;
}
.osp select:focus-visible {
  outline: 2px solid #34432c !important;
  outline-offset: 2px;
}
.osp select option, .osp select optgroup {
  background-color: #ead7aa !important;
  color: #34271b !important;
  font-family: inherit;
}
.osp select option:checked, .osp select option:hover, .osp select option:focus {
  background-color: #34432c !important;
  color: #fff0c8 !important;
}

@supports (appearance: base-select) {
  .osp select:not([multiple]):not([size]),
  .osp select:not([multiple]):not([size])::picker(select) {
    appearance: base-select;
  }
  .osp select::picker(select) {
    opacity: 1;
    background: #ead7aa;
    color: #34271b;
    border: 1px solid #8a642e;
    border-radius: 3px;
    padding: 3px;
    box-shadow: 0 4px 10px rgba(52, 39, 27, 0.25);
    font-family: "Handwritten", Georgia, serif;
  }
  .osp select option {
    padding: 5px 10px;
    border-radius: 2px;
    cursor: pointer;
    white-space: normal;
  }
  .osp select option:checked,
  .osp select option:hover,
  .osp select option:focus {
    box-shadow: none !important;
  }
